import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { FiChevronLeft, FiChevronRight } from 'react-icons/fi';

const BANNERS = [
  {
    id: 1,
    title: 'Summer Sale',
    subtitle: 'Up to 60% Off on Premium Eyewear',
    cta: 'Shop Now',
    link: '/sale/summer',
    gradient: 'linear-gradient(135deg, #2874f0 0%, #1a5dc7 50%, #0d47a1 100%)',
    accent: '#ff9f00',
  },
  {
    id: 2,
    title: 'New Arrivals',
    subtitle: 'Ray-Ban Collection 2026',
    cta: 'Explore',
    link: '/brands/ray-ban',
    gradient: 'linear-gradient(135deg, #1b1b2f 0%, #162447 50%, #1f4068 100%)',
    accent: '#e43f5a',
  },
  {
    id: 3,
    title: 'Blue Cut Lenses',
    subtitle: 'Starting ₹999 — Protect Your Eyes',
    cta: 'Buy Now',
    link: '/category/blue-cut',
    gradient: 'linear-gradient(135deg, #0f9b58 0%, #0d8a4e 50%, #0b7a43 100%)',
    accent: '#fff',
  },
  {
    id: 4,
    title: 'Virtual Try-On',
    subtitle: 'Try Before You Buy — From Home',
    cta: 'Try Now',
    link: '/virtual-try-on',
    gradient: 'linear-gradient(135deg, #6c63ff 0%, #5a52d5 50%, #4834d4 100%)',
    accent: '#ffd32a',
  },
];

const styles = {
  container: {
    position: 'relative',
    width: '100%',
    overflow: 'hidden',
    background: '#f1f3f6',
  },
  track: {
    display: 'flex',
    transition: 'transform 0.5s ease-in-out',
  },
  slide: {
    minWidth: '100%',
    height: '400px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    position: 'relative',
    cursor: 'pointer',
  },
  content: {
    textAlign: 'center',
    zIndex: 2,
    padding: '20px',
  },
  title: {
    fontSize: '48px',
    fontWeight: 700,
    color: '#fff',
    marginBottom: '12px',
    textShadow: '0 2px 8px rgba(0,0,0,0.3)',
    fontFamily: "'Roboto', sans-serif",
  },
  subtitle: {
    fontSize: '22px',
    color: 'rgba(255,255,255,0.9)',
    marginBottom: '24px',
    fontWeight: 400,
  },
  cta: {
    display: 'inline-block',
    padding: '12px 36px',
    borderRadius: '4px',
    fontWeight: 600,
    fontSize: '16px',
    textDecoration: 'none',
    transition: 'all 0.2s',
    textTransform: 'uppercase',
    letterSpacing: '0.5px',
  },
  arrow: {
    position: 'absolute',
    top: '50%',
    transform: 'translateY(-50%)',
    background: 'rgba(255,255,255,0.9)',
    border: 'none',
    borderRadius: '50%',
    width: '44px',
    height: '44px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    cursor: 'pointer',
    zIndex: 10,
    fontSize: '20px',
    color: '#333',
    boxShadow: '0 2px 8px rgba(0,0,0,0.15)',
    transition: 'all 0.2s',
  },
  dots: {
    position: 'absolute',
    bottom: '20px',
    left: '50%',
    transform: 'translateX(-50%)',
    display: 'flex',
    gap: '8px',
    zIndex: 10,
  },
  dot: {
    width: '10px',
    height: '10px',
    borderRadius: '50%',
    border: 'none',
    cursor: 'pointer',
    transition: 'all 0.3s',
  },
  glassesDecor: {
    position: 'absolute',
    fontSize: '120px',
    opacity: 0.1,
    right: '10%',
    top: '20%',
  },
};

export default function HeroCarousel() {
  const [current, setCurrent] = useState(0);
  const [paused, setPaused] = useState(false);

  const next = useCallback(() => {
    setCurrent((prev) => (prev + 1) % BANNERS.length);
  }, []);

  const prev = useCallback(() => {
    setCurrent((prev) => (prev - 1 + BANNERS.length) % BANNERS.length);
  }, []);

  useEffect(() => {
    if (paused) return;
    const timer = setInterval(next, 4000);
    return () => clearInterval(timer);
  }, [next, paused]);

  return (
    <div
      style={styles.container}
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
    >
      <div
        style={{
          ...styles.track,
          transform: `translateX(-${current * 100}%)`,
        }}
      >
        {BANNERS.map((banner) => (
          <Link
            to={banner.link}
            key={banner.id}
            style={{
              ...styles.slide,
              background: banner.gradient,
            }}
          >
            <div style={styles.glassesDecor}>👓</div>
            <div style={styles.content}>
              <div style={styles.title}>{banner.title}</div>
              <div style={styles.subtitle}>{banner.subtitle}</div>
              <span
                style={{
                  ...styles.cta,
                  background: banner.accent,
                  color: ['#fff', '#ffd32a'].includes(banner.accent) ? '#333' : '#fff',
                }}
              >
                {banner.cta}
              </span>
            </div>
          </Link>
        ))}
      </div>

      <button
        style={{ ...styles.arrow, left: '16px' }}
        onClick={(e) => { e.preventDefault(); prev(); }}
        aria-label="Previous"
      >
        <FiChevronLeft />
      </button>
      <button
        style={{ ...styles.arrow, right: '16px' }}
        onClick={(e) => { e.preventDefault(); next(); }}
        aria-label="Next"
      >
        <FiChevronRight />
      </button>

      <div style={styles.dots}>
        {BANNERS.map((_, i) => (
          <button
            key={i}
            style={{
              ...styles.dot,
              background: i === current ? '#fff' : 'rgba(255,255,255,0.5)',
              transform: i === current ? 'scale(1.2)' : 'scale(1)',
            }}
            onClick={() => setCurrent(i)}
            aria-label={`Slide ${i + 1}`}
          />
        ))}
      </div>

      <style>{`
        @media (max-width: 768px) {
          .hero-slide { height: 200px !important; }
        }
      `}</style>
    </div>
  );
}
